import{_ as s,o,c as r,a2 as a}from"./chunks/framework.F7eQ-ohH.js";const n="/bzygq/assets/quesion_imgs_5b48bafac3e744948f5bb82e056489cf.DdS-in6P.png",p="/bzygq/assets/quesion_imgs_28713143f39041d69ecdea4bb7073d91.CBfhMuY9.png",e="/bzygq/assets/quesion_imgs_fa0269fffb464975bf8bb736c3c4eed0.KYlRhIhL.png",g="/bzygq/assets/quesion_imgs_1125d3b5f91649d8b65c73ad195f6aae.DKZMD2Ag.png",f=JSON.parse('{"title":"单边线性植树：","description":"","frontmatter":{},"headers":[],"relativePath":"行测/数量分析/13.植树问题.md","filePath":"行测/数量分析/13.植树问题.md","lastUpdated":1788883925000}'),i={name:"行测/数量分析/13.植树问题.md"};function l(_,t,c,d,h,b){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="单边线性植树" tabindex="-1">单边线性植树： <a class="header-anchor" href="#单边线性植树" aria-label="Permalink to &quot;单边线性植树：&quot;">​</a></h1><p><img src="'+n+'" alt=""></p><ol><li><strong>棵数计算</strong>：棵数 = 总长 ÷ 间隔 + 1，此公式体现了在线性道路两端都种树的情况下，树的数量比间隔数多 1 的规律。</li><li><strong>总长计算</strong>：总长 = (棵数 - 1) × 间隔，通过已知树的棵数反推道路总长。</li></ol><h1 id="单边环形植树" tabindex="-1">单边环形植树： <a class="header-anchor" href="#单边环形植树" aria-label="Permalink to &quot;单边环形植树：&quot;">​</a></h1><p><img src="'+p+'" alt=""></p><ol><li><strong>棵数计算</strong>：棵数 = 总长 ÷ 间 隔，因为环形是封闭线路，树的棵数和间隔数是相等的。</li><li><strong>总长计算</strong>：总长 = 棵数 × 间隔，根据树的棵数来确定环形线路的长度。</li></ol><h1 id="单边楼间植树" tabindex="-1">单边楼间植树： <a class="header-anchor" href="#单边楼间植树" aria-label="Permalink to &quot;单边楼间植树：&quot;">​</a></h1><p><img src="'+e+'" alt=""></p><ol><li><strong>棵数计算</strong>：棵数 = 总长 ÷ 间隔 - 1，适用于在两楼等建筑物之间种树，两端是建筑物不能种树，所以树的棵数比间隔数少 1。</li><li><strong>总长计算</strong>：总长 = (棵数 + 1) × 间隔，由树的棵数推算出相应的总长度。</li></ol><h1 id="双边植树" tabindex="-1">双边植树 <a class="header-anchor" href="#双边植树" aria-label="Permalink to &quot;双边植树&quot;">​</a></h1><p><img src="'+g+'" alt=""></p><p>在单边植树计算结果的基础上乘以 2，即得到道路两侧种树的总棵数。</p><h1 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h1><p><strong>1、把一根钢管锯成 5 段需要 8 分钟，如果把同样的钢管锯成 20 段需要多少分钟？（ ）</strong></p><p>A. 32 分钟 B. 38 分钟 C. 40 分钟 D. 152 分钟</p><p><strong>答案</strong>：B</p><p><strong>解析</strong>： 锯钢管时，段数与锯的次数关系为：次数 = 段数 - 1， 锯成 5 段需锯的次数：5 - 1 = 4（次），耗时 8 分钟，因此每次锯管时间为：8÷4 = 2（分钟），锯成 20 段需锯的次数：20 - 1 = 19（次），总耗时为：19×2 = 38（分钟）。</p><p><strong>2、 一人从一楼走到四楼，共走了 54 级台阶。若每层楼之间台阶数相同，他从一楼走到八楼一共要走多少级台阶？（ ）</strong></p><p>A. 126 B. 120 C. 114 D. 108</p><p><strong>答案</strong>：A</p><p><strong>解析</strong>： 从一楼到四楼，楼层间隔数为：4 - 1 = 3（层），共 54 级台阶，因此每层台阶数为：54÷3 = 18（级），从一楼到八楼的楼层间隔数：8 - 1 = 7（层），总台阶数为：18×7 = 126（级）。</p><p><strong>3、老张家住在第 6 层楼，若每层楼间楼梯台阶都是 14 级，老张每次来回要走多少级台阶？（ ）</strong></p><p>A. 84 B. 70 C. 168 D. 140</p><p><strong>答案</strong>：D</p><p><strong>解析</strong>： 从 1 楼到 6 楼的楼层间隔数：6 - 1 = 5（层），单程台阶数为：5×14 = 70（级），“来回”指去程和返程，总台阶数为：70×2 = 140（级）。</p><p><strong>4、正方形池塘每边种 17 棵树，四个角都种，树间距为 2 米，求池塘周长？（ ）</strong></p><p>A. 125 B. 126 C. 127 D. 128</p><p><strong>答案</strong>：D</p><p><strong>解析</strong>： 正方形每边种树 17 棵，由于四个角的树重复计算，每边实际间隔数为：17 - 1 = 16（个）。 每个间隔 2 米，单边长为：16×2 = 32（米）。 正方形周长 = 边长×4，即：32×4 = 128（米）。</p><p><strong>5、在路两旁栽树，两棵树间距 5 米，刚好栽满 100 棵树，求这条路总长？（ ）</strong></p><p>A. 500</p><p>B. 495</p><p>C. 250</p><p>D. 245</p><p><strong>答案</strong>：D</p><p><strong>解析</strong>： 路两旁共栽 100 棵树，因此每旁栽树：100÷2 = 50（棵）。 单边栽树 50 棵时，间隔数 = 棵数 - 1，即：50 - 1 = 49（个）。 每个间隔 5 米，路长为：49×5 = 245（米）。</p>',36)])])}const u=s(i,[["render",l]]);export{f as __pageData,u as default};
